import React, { useState } from 'react';
import { Outlet, NavLink } from 'react-router-dom';

const TrangChuCuDan = () => {
    // 1. Quản lý trạng thái khai báo thông tin
    const [user, setUser] = useState({
        hoTen: '', // Để trống để test bộ lọc khai báo
        soPhong: '',
        isKhaiBao: false
    });

    const menuItems = [
        { name: 'Trung tâm thông báo', path: 'thong-bao', icon: '🔔' },
        { name: 'Thông tin cá nhân', path: 'thong-tin', icon: '👤' },
        { name: 'Hoá đơn & Phí', path: 'hoa-don', icon: '📄' },
        { name: 'Yêu cầu bảo trì', path: 'bao-tri', icon: '🔧' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien', icon: '🚗' },
        { name: 'Đăng ký bãi đỗ', path: 'dang-ky-xe', icon: '🅿️' },
    ];

    // Hàm xử lý sau khi điền Form khai báo
    const handleConfirmKhaiBao = (data) => {
        setUser({
            hoTen: data.hoTen,
            soPhong: data.soPhong,
            isKhaiBao: true
        });
    };

    return (
        <div style={styles.container}>
            {/* 1. Sidebar - Sử dụng Glassmorphism tối giống Admin */}
            <aside style={styles.sidebar} className="glass-sidebar">
                <div style={styles.logoBox}>
                    <h1 style={styles.logoText}>A&RMS</h1>
                    <p style={styles.subLogo}>RESIDENT</p>
                </div>

                <nav style={styles.navMenu}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-cu-dan/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navLink,
                                backgroundColor: isActive ? '#48bb78' : 'rgba(255, 255, 255, 0.8)',
                                color: isActive ? '#fff' : '#333',
                                backgroundImage: isActive ? 'none' : "url('../assets/nền của các nút chính.jpg')",
                                backgroundSize: 'cover'
                            })}
                        >
                            <span style={{marginRight: '10px'}}>{item.icon}</span>
                            {item.name}
                        </NavLink>
                    ))}
                </nav>
            </aside>

            {/* 2. Vùng nội dung bên phải */}
            <div style={styles.contentArea}>
                <header style={styles.headerTop} className="glass-sidebar">
                    <span style={styles.headerTitle}>Dịch vụ cư dân trực tuyến</span>

                    <div style={styles.userInfo}>
                        <div style={styles.userText}>
                            <div style={{fontWeight: 'bold'}}>{user.hoTen || 'Khách'}</div>
                            <div style={{fontSize: '11px', opacity: 0.8}}>{user.soPhong ? `Phòng ${user.soPhong}` : 'Chưa xác thực'}</div>
                        </div>
                        <div style={styles.avatar} />
                    </div>
                </header>

                <main style={styles.mainContent}>
                    {/* KIỂM TRA: Nếu chưa khai báo thì hiện Form, nếu rồi thì hiện nội dung trang con */}
                    {!user.isKhaiBao ? (
                        <KhaiBaoForm onConfirm={handleConfirmKhaiBao} />
                    ) : (
                        <Outlet /> 
                    )}
                </main>
            </div>
        </div>
    );
};

// --- Component phụ: Form khai báo (hiện ngay trong ô bên phải) ---
const KhaiBaoForm = ({ onConfirm }) => {
    const [formData, setFormData] = useState({ hoTen: '', soPhong: '', sdt: '' });

    return (
        <div className="glass-card fade-in" style={styles.formBox}>
            <h2 style={{color: '#2e7d32'}}>👋 Chào mừng bạn về nhà!</h2>
            <p style={{marginBottom: '25px', color: '#666'}}>Vui lòng xác nhận thông tin để tiếp tục.</p>
            <input 
                style={styles.input} 
                placeholder="Họ và tên của bạn..." 
                onChange={(e) => setFormData({...formData, hoTen: e.target.value})}
            />
            <input 
                style={styles.input} 
                placeholder="Số phòng (Vd: 101)..." 
                maxLength="3"
                onChange={(e) => setFormData({...formData, soPhong: e.target.value})}
            />
            <input 
                style={styles.input} 
                placeholder="Số điện thoại..." 
                onChange={(e) => setFormData({...formData, sdt: e.target.value})}
            />
            <button 
                style={styles.btnConfirm}
                onClick={() => onConfirm(formData)}
            >
                Bắt đầu sử dụng
            </button>
        </div>
    );
};

const styles = {
    container: { 
        display: 'flex', 
        height: '100vh', 
        padding: '15px', 
        gap: '15px', 
        boxSizing: 'border-box',
        backgroundImage: "url('../assets/nền dưới cùng.jpg')",
        backgroundSize: 'cover'
    },
    sidebar: { width: '270px', borderRadius: '30px', display: 'flex', flexDirection: 'column', overflow: 'hidden' },
    logoBox: { padding: '40px 20px', textAlign: 'center' },
    logoText: { color: '#fff', fontSize: '32px', fontWeight: '900', margin: 0 },
    subLogo: { color: '#48bb78', fontSize: '12px', fontWeight: 'bold', letterSpacing: '4px' },
    navMenu: { flex: 1, padding: '0 20px', display: 'flex', flexDirection: 'column', gap: '10px' },
    navLink: { padding: '14px 20px', borderRadius: '18px', textDecoration: 'none', fontWeight: 'bold', fontSize: '13px', transition: '0.3s', display: 'flex', alignItems: 'center' },
    contentArea: { flex: 1, display: 'flex', flexDirection: 'column', gap: '15px' },
    headerTop: { height: '70px', borderRadius: '25px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 25px' },
    headerTitle: { color: '#fff', fontSize: '16px', fontWeight: '600' },
    userInfo: { display: 'flex', alignItems: 'center', gap: '12px', color: '#fff' },
    userText: { textAlign: 'right' },
    avatar: { width: '40px', height: '40px', borderRadius: '50%', border: '2px solid #48bb78', backgroundImage: "url('../assets/nền của admin.jpg')", backgroundSize: 'cover' },
    mainContent: { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center' },
    formBox: { width: '450px', padding: '40px', textAlign: 'center', backgroundColor: 'rgba(255,255,255,0.95)' },
    input: { width: '100%', padding: '15px', borderRadius: '12px', border: '1px solid #ddd', marginBottom: '15px', outline: 'none' },
    btnConfirm: { width: '100%', padding: '15px', borderRadius: '12px', border: 'none', backgroundColor: '#48bb78', color: '#fff', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer' }
};

export default TrangChuCuDan;
